INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass regelmäßiger Aufgabenwechsel immer die Produktivität steigert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Person und Organisation ab"}, {"text": "Ja", "correct": false, "because": "Nicht universell zutreffend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Kollegen zwischen IT-Aufgaben rotieren lasse?', 3, '[{"text": "Wissenstransfer", "correct": true, "because": "Fördert Teamkompetenz"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität ist wichtiger"}, {"text": "Hardwarezuweisung", "correct": false, "because": "Nicht primär relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützen einen effektiven Wechsel zwischen Aufgaben?', 5, '[{"text": "Klare Dokumentation", "correct": true, "because": "Erleichtert Einarbeitung"}, {"text": "Schulungen", "correct": true, "because": "Vermittelt neues Wissen"}, {"text": "Höhere Gehälter", "correct": false, "because": "Motiviert, aber nicht zentral"}, {"text": "Weniger Planung", "correct": false, "because": "Kann Chaos verursachen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Aufgabenwechsel fördert Flexibilität. b) Er führt immer zu längeren Einarbeitungszeiten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einarbeitung nicht zwangsläufig lang"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Kollegen zwischen Netzwerk- und Softwareaufgaben rotieren lasse?', 4, '[{"text": "Vorkenntnisse", "correct": false, "because": "Müssen geprüft werden"}, {"text": "Kommunikation", "correct": false, "because": "Schlüssel für Erfolg"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Aufgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Wechsel zwischen Aufgaben immer Schulungen braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Vorwissen kann ausreichen"}, {"text": "Ja", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich jemanden von Support zu Serverwartung rotieren lasse?', 3, '[{"text": "Breiteres Wissen", "correct": true, "because": "Fördert Vielseitigkeit"}, {"text": "Schnellere Ergebnisse", "correct": false, "because": "Lernen braucht Zeit"}, {"text": "Weniger Dokumentation", "correct": false, "because": "Nicht das Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen einen Aufgabenwechsel erfolgreich?', 5, '[{"text": "Teamunterstützung", "correct": true, "because": "Erleichtert Übergang"}, {"text": "Klare Ziele", "correct": true, "because": "Gibt Orientierung"}, {"text": "Höhere Bandbreite", "correct": false, "because": "Technisch irrelevant"}, {"text": "Weniger Kontrolle", "correct": false, "because": "Kann Verwirrung stiften"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Wechsel fördert Teamzusammenhalt. b) Er verzögert immer Projekte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verzögerungen sind nicht zwangsläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Kollegen zwischen IT-Rollen zu rotieren?', 4, '[{"text": "Planung", "correct": false, "because": "Strukturiert Übergang"}, {"text": "Feedback", "correct": false, "because": "Fördert Lernen"}, {"text": "Farbkodierung", "correct": true, "because": "Irrelevant für Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Wechsel zwischen Aufgaben immer chaotisch?', 2, '[{"text": "Nein", "correct": true, "because": "Planung minimiert Chaos"}, {"text": "Ja", "correct": false, "because": "Struktur hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern das Lernen bei einem Wechsel?', 4, '[{"text": "Mentoring", "correct": true, "because": "Bietet direkte Hilfe"}, {"text": "Dokumentation", "correct": true, "because": "Liefert Nachschlagewerk"}, {"text": "Schnelle Hardware", "correct": false, "because": "Nicht lernrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Aufgabenwechsel nur für Junioren nützlich ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Alle profitieren von Vielseitigkeit"}, {"text": "Ja", "correct": false, "because": "Auch Senioren lernen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um einen Wechsel zu Netzwerkaufgaben vorzubereiten?', 3, '[{"text": "Schulungsplan", "correct": true, "because": "Vermittelt relevantes Wissen"}, {"text": "Neuer Laptop", "correct": false, "because": "Nicht primär nötig"}, {"text": "Farbcodierte Pläne", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Wechsel reduziert Monotonie. b) Er erfordert immer neue Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Wechsel zwischen IT-Rollen?', 5, '[{"text": "Breitere Kompetenz", "correct": true, "because": "Fördert Vielseitigkeit"}, {"text": "Bessere Zusammenarbeit", "correct": true, "because": "Verständnis wächst"}, {"text": "Schnellere Hardware", "correct": false, "because": "Nicht relevant"}, {"text": "Weniger Planung", "correct": false, "because": "Planung ist nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Wechsel zu Datenbankaufgaben unwichtig?', 3, '[{"text": "SQL-Kenntnisse", "correct": false, "because": "Zentral für Aufgabe"}, {"text": "Dokumentation", "correct": false, "because": "Hilft beim Lernen"}, {"text": "Bürodeko", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Fördert ein Wechsel immer die Spezialisierung?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus liegt auf Vielseitigkeit"}, {"text": "Ja", "correct": false, "because": "Ziel ist Breite"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Wechsel die Teamdynamik verbessert?', 2, '[{"text": "Ja", "correct": true, "because": "Verständnis wächst"}, {"text": "Nein", "correct": false, "because": "Dynamik profitiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, wenn ich jemanden zu Sicherheitsaufgaben rotieren lasse?', 4, '[{"text": "Schulung in Sicherheit", "correct": true, "because": "Vermittelt Fachwissen"}, {"text": "Neuer Monitor", "correct": false, "because": "Nicht nötig"}, {"text": "Schnellere CPU", "correct": false, "because": "Irrelevant"}]');
